def _vp_dispatch():
    a = _vs.argv
    if not (len(a) >= 2 and str(a[1]).lower().endswith(".py")):
        return
    script = a[1]
    name = _vo.path.splitext(_vo.path.basename(script))[0]
    try:
        _vs.argv = [script] + list(a[2:])
        d = _vo.path.dirname(_vo.path.abspath(script))
        if d and d not in _vs.path:
            _vs.path.insert(0, d)
        import importlib
        m = None
        try:
            m = importlib.import_module(name)
        except ImportError:
            m = None
        fn = getattr(m, "main", None) if m is not None else None
        if callable(fn):
            fn()
        else:
            import runpy
            runpy.run_path(script, run_name="__main__")
    except SystemExit:
        raise
    except BaseException:
        try:
            import traceback, tempfile
            with open(_vo.path.join(tempfile.gettempdir(), "vp_dispatch_error.log"), "a", encoding="utf-8") as _f:
                _f.write("[" + name + "]\n" + traceback.format_exc() + "\n")
        except Exception:
            pass
        _vs.exit(1)
    _vs.exit(0)
_vp_dispatch()
