VP_REGEN_HOVER_BOX_JS = """() => {
    try {
        const msgs = Array.from(document.querySelectorAll('div, p')).filter(el => {
            const t = (el.innerText || '');
            return t && t.length < 2000 && /SEEDANCE_UNAVAILABLE|currently unavailable|try again later/i.test(t);
        });
        let el = msgs.length ? msgs[msgs.length - 1] : null;
        if (!el) {
            const all = Array.from(document.querySelectorAll('div')).filter(d => (d.innerText || '').length > 3);
            el = all.length ? all[all.length - 1] : null;
        }
        if (!el) return null;
        const r = el.getBoundingClientRect();
        if (r.width < 10 || r.height < 10) return null;
        return { x: r.left + Math.min(r.width / 2, 300), y: r.top + 10 };
    } catch (e) { return null; }
}"""
REGEN_INSET_CLICK_JS = """() => {
    try {
        const pop = document.querySelector('[role="menu"], [data-radix-menu-content]');
        if (pop) {
            document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape', bubbles: true}));
        }
        const allBtns = Array.from(document.querySelectorAll('button, [role="button"]'));
        let targetBtn = allBtns.find(b => {
            const al = ((b.getAttribute('aria-label') || '') + ' ' + (b.getAttribute('title') || '')).toLowerCase();
            return al.includes('regenerate') || al.includes('retry') || al.includes('try again') || al.includes('re-generate');
        });
        if (!targetBtn) {
            const cands = Array.from(document.querySelectorAll('button')).filter(b => {
                const r = b.getBoundingClientRect();
                return r.width >= 12 && r.width <= 48 && r.height >= 12 && r.height <= 48;
            });
            const tops = {};
            for (const b of cands) {
                const k = Math.round(b.getBoundingClientRect().top / 6);
                (tops[k] = tops[k] || []).push(b);
            }
            let bestRow = null;
            for (const k in tops) {
                if (tops[k].length >= 4) bestRow = tops[k];
            }
            if (bestRow) {
                bestRow.sort((a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left);
                const filtered = bestRow.filter(el => {
                    const t = (el.innerText || el.textContent || '').trim();
                    const al = ((el.getAttribute('aria-label') || '') + ' ' + (el.getAttribute('title') || '')).toLowerCase();
                    return !(t === '⋯' || t === '...' || t === '…' || al.includes('more') || al.includes('menu'));
                });
                if (filtered.length) {
                    targetBtn = filtered[filtered.length - 1];
                }
            }
        }
        if (!targetBtn) return null;
        const overlay = targetBtn.querySelector('div[class*="inset-[-6px]"]') || 
                        targetBtn.querySelector('div.opacity-0') || 
                        targetBtn.querySelector('div[class*="absolute"]') || 
                        targetBtn;
        const r = overlay.getBoundingClientRect();
        const cx = r.left + r.width / 2;
        const cy = r.top + r.height / 2;
        const opts = { bubbles: true, cancelable: true, view: window, clientX: cx, clientY: cy };
        ['pointerdown', 'mousedown', 'pointerup', 'mouseup', 'click'].forEach(evt => {
            try { overlay.dispatchEvent(new MouseEvent(evt, opts)); } catch(e){}
        });
        try { overlay.click(); } catch(e){}
        if (overlay !== targetBtn) {
            try { targetBtn.click(); } catch(e){}
        }
        return { ok: true, x: cx, y: cy };
    } catch(e) {
        return null;
    }
}"""

