_VP_DRIVE_SKILL_CACHE = {"url": "", "path": "", "ts": 0.0}



















def vp_drive_direct_url(url):









    # skill-drive-fix-v1: koi bhi Drive share link -> direct download link









    try:









        import re as _redrv









        m = _redrv.search(r"drive\.google\.com/(?:file/d/|uc\?id=|open\?id=)([a-zA-Z0-9_-]{10,})", url or "")









        if m:









            return f"https://drive.google.com/uc?export=download&id={m.group(1)}"









        if (url or "").strip().startswith("http"):









            return url.strip()









    except Exception:









        pass









    return ""



















def vp_fetch_admin_skill_drive_url():









    # skill-drive-fix-v1: admin panel /admin/settings se skill_drive_url live read









    try:









        api_url = (sub_load_cfg() or {}).get("url") or SUB_API_URL_DEFAULT









        for _pl in ({"op": "list"}, {"action": "list"}, {"op": "get", "key": "skill_drive_url"}, {}):









            try:









                res = sub_api_at(api_url, "/admin/settings", _pl)









            except Exception:









                continue









            rows = None









            if isinstance(res, dict):









                rows = res.get("settings") or res.get("rows") or res.get("data")









            if isinstance(rows, dict):









                v = str(rows.get("skill_drive_url") or rows.get("update_skill") or rows.get("skill_url") or "").strip()









                if v:









                    return v









                rows = [rows]









            if isinstance(rows, list):









                for item in rows:









                    if isinstance(item, dict):









                        k = str(item.get("key", "") or "").lower()









                        if k in ("skill_drive_url", "update_skill", "skill_url"):









                            v = str(item.get("value", "") or "").strip()









                            if v:









                                return v









    except Exception:









        pass









    return ""



















def vp_drive_skill_path(ttl=300):









    # skill-drive-fix-v1: Drive se SKILL.md download karke path do (fail/empty => purana local/code fallback safe)









    try:









        now = time.time()









        c = _VP_DRIVE_SKILL_CACHE









        if c.get("url") and c.get("path") and os.path.isfile(c["path"]) and (now - c.get("ts", 0)) < ttl:









            return c["path"]









        url = vp_fetch_admin_skill_drive_url()









        if not url:









            if c.get("path") and os.path.isfile(c["path"]):









                return c["path"]









            return ""









        durl = vp_drive_direct_url(url)









        if not durl:









            return ""









        import tempfile as _tfdrv









        import urllib.request as _urdrv









        dest_dir = os.path.join(_tfdrv.gettempdir(), "VidoProSkillDrive")









        os.makedirs(dest_dir, exist_ok=True)









        dest = os.path.join(dest_dir, "SKILL.md")









        if c.get("url") == url and os.path.isfile(dest) and os.path.getsize(dest) > 50:









            _VP_DRIVE_SKILL_CACHE.update({"url": url, "path": dest, "ts": now})









            return dest









        req = _urdrv.Request(durl, headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"})









        with _urdrv.urlopen(req, timeout=60) as resp:









            data = resp.read()









        if not data or len(data) < 50:









            if c.get("path") and os.path.isfile(c["path"]):









                return c["path"]









            return ""









        with open(dest, "wb") as f:









            f.write(data)









        _VP_DRIVE_SKILL_CACHE.update({"url": url, "path": dest, "ts": now})









        try:









            print(f"🧠 [SKILL-DRIVE] Nayi skill Drive se download ho gayi: {dest}")









        except Exception:









            pass









        return dest









    except Exception:









        try:









            if _VP_DRIVE_SKILL_CACHE.get("path") and os.path.isfile(_VP_DRIVE_SKILL_CACHE["path"]):









                return _VP_DRIVE_SKILL_CACHE["path"]









        except Exception:









            pass









        return ""



















