def vp_detect_current_kind():









    # skill-drive-fix-v5: call-stack se caller ka has_images / task.images dekho => "img" ya "text"









    try:









        import inspect









        fr = inspect.currentframe()









        for _i in range(14):









            fr = fr.f_back if fr else None









            if not fr:









                break









            _loc = fr.f_locals









            if "has_images" in _loc:









                return "img" if _loc.get("has_images") else "text"









            if "task" in _loc:









                _t = _loc.get("task")









                _imgs = getattr(_t, "images", None) if _t is not None else None









                return "img" if _imgs else "text"









        return "text"









    except Exception:









        return "text"



















