VP_M1_DOTS_JS = """(filterText) => {









  try {









    const re = new RegExp(filterText, 'i');









    const rows = Array.from(document.querySelectorAll('div, li')).filter(el => {









      const r = el.getBoundingClientRect();









      if (r.width < 260 || r.height < 40 || r.height > 170) return false;









      const t = (el.innerText||'');









      return re.test(t) && t.length <= 400;









    });









    if (!rows.length) return false;









    rows.sort((a,b) => (a.innerText||'').length - (b.innerText||'').length);









    const row = rows[0];









    const btns = Array.from(row.querySelectorAll('button, [role="button"]'));









    const isSwitch = (b) => (b.getAttribute('role') === 'switch') || (b.hasAttribute('aria-checked')) || (b.tagName === 'INPUT') || ((b.getAttribute('type')||'') === 'checkbox');









    const sizeOk = (b) => { const r = b.getBoundingClientRect(); return r.width >= 8 && r.height >= 8 && r.width <= 70 && r.height <= 45; };









    const cand = btns.filter(b => sizeOk(b) && !isSwitch(b));









    let dots = cand.find(b => { const t = (b.textContent||'').trim(); return t === '...' || t === '⋯' || t === '•••'; });









    if (!dots) dots = cand.find(b => { const al = ((b.getAttribute('aria-label')||'') + ' ' + (b.getAttribute('title')||'')).toLowerCase(); return al.includes('more') || al.includes('menu') || al.includes('option'); });









    if (!dots) { const si = btns.findIndex(isSwitch); if (si > 0 && cand.indexOf(btns[si-1]) >= 0) dots = btns[si-1]; }









    if (!dots) dots = cand.length ? cand[cand.length-1] : null;









    if (!dots) return false;









    dots.click();









    return true;









  } catch(e){ return false; }









}"""









# method1-fix-v9: broad try matcher + dispatch click









VP_M1_TRY_JS = """() => {









  try {









    const els = Array.from(document.querySelectorAll('button, [role="menuitem"], [role="option"], div, span, li, p'));









    const c = els.filter(el => {









      const t = (el.innerText|| el.textContent|| '').trim();









      if (!/^Try in New Chat/i.test(t)) return false;









      if (t.length > 40) return false;









      const r = el.getBoundingClientRect();









      return r.width > 8 && r.height > 6 && r.width < 460;









    });









    if (!c.length) return false;









    c.sort((a,b) => (a.innerText||'').length - (b.innerText||'').length);









    const el = c[0];









    const target = el.closest('button, [role="menuitem"], [role="option"], li') || el;









    target.click();









    ['pointerdown','mousedown','pointerup','mouseup','click'].forEach(tp => { try { target.dispatchEvent(new MouseEvent(tp, {bubbles:true, cancelable:true, view:window})); } catch(e){} });









    return true;









  } catch(e){ return false; }









}"""









