VP_M1_DOTS_BOX_JS = """(filterText) => {









  try {









    const re = new RegExp(filterText, 'i');









    const rows = Array.from(document.querySelectorAll('div, li')).filter(el => {









      const r = el.getBoundingClientRect();









      if (r.width < 260 || r.height < 40 || r.height > 170) return false;









      const t = (el.innerText||'');









      return re.test(t) && t.length <= 400;









    });









    if (!rows.length) return null;









    rows.sort((a,b) => (a.innerText||'').length - (b.innerText||'').length);









    const row = rows[0];









    const vis = (b) => { const r = b.getBoundingClientRect(); if (r.width < 6 || r.height < 6) return false; const st = window.getComputedStyle(b); return st.display !== 'none' && st.visibility !== 'hidden' && parseFloat(st.opacity||'1') > 0.05; };









    const isSwitch = (b) => (b.getAttribute('role') === 'switch') || (b.hasAttribute('aria-checked')) || (b.tagName === 'INPUT') || ((b.getAttribute('type')||'') === 'checkbox');









    const all = Array.from(row.querySelectorAll('button, [role="button"]')).filter(vis);









    const cand = all.filter(b => !isSwitch(b));









    let dots = cand.find(b => { const al = ((b.getAttribute('aria-label')||'') + ' ' + (b.getAttribute('title')||'') + ' ' + (b.getAttribute('data-slot')||'')).toLowerCase(); return al.includes('more') || al.includes('menu') || al.includes('option') || al.includes('dropdown'); });









    if (!dots) dots = cand.find(b => { const t = (b.textContent||'').trim(); return t === '...' || t === '⋯' || t === '•••'; });









    if (!dots) dots = cand.find(b => { const t = (b.textContent||'').trim(); return t === '' && b.querySelector('svg'); });









    if (!dots) { const si = all.findIndex(isSwitch); if (si > 0) dots = all[si-1]; }









    if (!dots && cand.length) dots = cand[cand.length-1];









    if (!dots) return null;









    const r = dots.getBoundingClientRect();









    return {x: r.left + r.width/2, y: r.top + r.height/2};









  } catch(e){ return null; }









}"""



















