VP_M1_TRY_CLICK_JS = """() => {









  try {









    let t = Array.from(document.querySelectorAll('[role="menuitem"], [data-slot="dropdown-menu-item"]')).find(el => /^Try in New Chat/i.test((el.innerText|| el.textContent|| '').trim()));









    if (!t) {









      t = Array.from(document.querySelectorAll('button, div, span, li, p')).find(el => (el.innerText|| el.textContent|| '').trim() === 'Try in New Chat');









    }









    if (!t) return false;









    const target = t.closest('[role="menuitem"]') || t;









    const r = target.getBoundingClientRect();









    const cx = r.left + r.width/2, cy = r.top + r.height/2;









    const mkP = (type) => new PointerEvent(type, {bubbles:true, cancelable:true, view:window, clientX:cx, clientY:cy, button:0, buttons:1, pointerId:1, pointerType:'mouse', isPrimary:true});









    const mkM = (type) => new MouseEvent(type, {bubbles:true, cancelable:true, view:window, clientX:cx, clientY:cy, button:0});









    try { target.dispatchEvent(mkP('pointerdown')); } catch(e){}









    try { target.dispatchEvent(mkM('mousedown')); } catch(e){}









    try { target.dispatchEvent(mkP('pointerup')); } catch(e){}









    try { target.dispatchEvent(mkM('mouseup')); } catch(e){}









    try { target.dispatchEvent(mkM('click')); } catch(e){}









    try { target.click(); } catch(e){}









    return true;









  } catch(e){ return false; }









}"""



















VP_M1_FOCUS_END_JS = """() => {









  try {









    const ed = document.querySelector('[contenteditable="true"], textarea');









    if (!ed) return false;









    ed.focus();









    try {









      if (ed.tagName === 'TEXTAREA') { ed.selectionStart = ed.selectionEnd = (ed.value||'').length; }









      else {









        const sel = window.getSelection();









        const rg = document.createRange();









        rg.selectNodeContents(ed);









        rg.collapse(false);









        sel.removeAllRanges();









        sel.addRange(rg);









      }









    } catch(e){}









    return true;  // method1-fix-v14 focus-end (no clear, no select-all)









  } catch(e){ return false; }









}"""



















