# ==================== toggle-guard-fix-v28 / chip-gate-fix-v28 ====================
VP_M1_TOGGLE_STATE_JS = """(name) => {
    try {
        const sws = Array.from(document.querySelectorAll('[role="switch"], input[type="checkbox"], [class*="toggle" i], [class*="switch" i]'));
        for (const sw of sws) {
            const host = sw.closest('div,li,tr');
            if (!host) continue;
            const t = (host.textContent || '');
            if (t && t.length < 300 && /dola\\s*seedance/i.test(t)) {
                const on = (sw.getAttribute('aria-checked') === 'true') || (sw.checked === true) || (String(sw.getAttribute('data-state')||'').toLowerCase() === 'on');
                return !!on;
            }
        }
        return null;
    } catch (e) { return null; }
}"""
VP_M1_TOGGLE_ON_JS = """(name) => {
    try {
        const sws = Array.from(document.querySelectorAll('[role="switch"], input[type="checkbox"], [class*="toggle" i], [class*="switch" i]'));
        for (const sw of sws) {
            const host = sw.closest('div,li,tr');
            if (!host) continue;
            const t = (host.textContent || '');
            if (t && t.length < 300 && /dola\\s*seedance/i.test(t)) {
                const on = (sw.getAttribute('aria-checked') === 'true') || (sw.checked === true);
                if (!on) { sw.click(); return true; }
                return true;
            }
        }
        return false;
    } catch (e) { return false; }
}"""
VP_M1_POINT_SAFE_JS = """(pt) => {
    try {
        const el = document.elementFromPoint(pt.x, pt.y);
        if (!el) return false;
        const bad = el.closest('[role="switch"], input[type="checkbox"], [class*="toggle" i], [class*="switch" i], [aria-checked]');
        return !bad;
    } catch (e) { return false; }
}"""
VP_M1_CHIP_ANY_JS = r"""() => {
    try {
        const eds = Array.from(document.querySelectorAll('[contenteditable="true"], [role="textbox"], textarea'));
        for (const ed of eds) {
            const t = (ed.innerText || ed.textContent || ed.value || '');
            if (/dola\s*seedance/i.test(t)) return true;
            let root = ed;
            for (let i = 0; i < 6 && root; i++) {
                root = root.parentElement;
                if (!root) break;
                const chip = Array.from(root.querySelectorAll('[class*="chip" i], [class*="tag" i], [data-business-resource-kind="skill"], span, div')).find(el => {
                    const tt = (el.textContent || '').trim();
                    if (!tt || tt.length > 60) return false;
                    if (!/dola\s*seedance/i.test(tt)) return false;
                    const r = el.getBoundingClientRect();
                    return r.width >= 4 && r.height >= 4;
                });
                if (chip) return true;
            }
        }
        return false;
    } catch (e) { return false; }
}"""


def vp_m1_toggle_ensure(engine, page):  # toggle-guard-fix-v28 — toggle OFF mila to ON, warna NEVER touch
    try:
        st = page.evaluate(VP_M1_TOGGLE_STATE_JS, "Dola Seedance")
        if st is False:
            ok = page.evaluate(VP_M1_TOGGLE_ON_JS, "Dola Seedance")
            engine.app.log(f"⚙️ Method 1: skill toggle OFF mila — ON kar diya (state={ok}).")
        return True
    except Exception:
        return True


def vp_m1_safe_dots_click(engine, page, dbox):  # toggle-guard-fix-v28 — 3-dot point par toggle ho to REAL click SKIP
    try:
        safe = True
        try:
            safe = bool(page.evaluate(VP_M1_POINT_SAFE_JS, {"x": dbox["x"], "y": dbox["y"]}))
        except Exception:
            safe = False
        if safe:
            try:
                page.mouse.click(dbox["x"], dbox["y"])
                return True
            except Exception:
                return False
        try:
            engine.app.log("⚙️ Method 1: 3-dot point par toggle/switch mila — REAL click skip kiya (toggle safe).")
        except Exception:
            pass
        return False
    except Exception:
        return False


def vp_m1_chip_gate(engine, page, secs=25):  # chip-gate-fix-v28 — chip confirm ke bina aage KABHI nahi
    t = time.time()
    while time.time() - t < secs:
        ok = False
        try:
            ok = bool(page.evaluate(VP_M1_CHIP_JS, "Dola Seedance"))
        except Exception:
            ok = False
        if not ok:
            try:
                ok = bool(page.evaluate(VP_M1_CHIP_ANY_JS))
            except Exception:
                ok = False
        if ok:
            return True
        time.sleep(0.5)
    return False

# ==================== chip-gate-fix-v29 ====================
VP_M1_CHIP_EDITOR_JS = """() => {
    try {
        const eds = Array.from(document.querySelectorAll('[contenteditable="true"], [role="textbox"], textarea'));
        for (const ed of eds) {
            const t = (ed.innerText || ed.textContent || ed.value || '');
            if (/dola\s*seedance/i.test(t)) return true;
            if (ed.querySelector('[data-business-resource-kind="skill"], [class*="chip" i]')) return true;
            let root = ed;
            for (let i = 0; i < 6 && root; i++) {
                root = root.parentElement;
                if (!root) break;
                const ch = Array.from(root.querySelectorAll('[data-business-resource-kind="skill"], [class*="chip" i], [class*="tag" i]')).find(el => {
                    const tt = (el.innerText || el.textContent || '');
                    return tt && tt.length < 60 && /dola\s*seedance/i.test(tt);
                });
                if (ch) return true;
            }
        }
        return false;
    } catch (e) { return false; }
}"""


def vp_m1_chip_seen(page):  # chip-gate-fix-v29 — robust chip detection (3 layers)
    try:
        if bool(page.evaluate(VP_M1_CHIP_JS, "Dola Seedance")):
            return True
    except Exception:
        pass
    try:
        if bool(page.evaluate(VP_M1_CHIP_ANY_JS)):
            return True
    except Exception:
        pass
    try:
        if bool(page.evaluate(VP_M1_CHIP_EDITOR_JS)):
            return True
    except Exception:
        pass
    return False

