VPACK_MAGIC = b"VPX6"









VPACK_VERSION = 1









VPACK_SECRET = "VidoPro-Zakariya-Seedance25-Priv8-2026-!x9Qm#Lp7WvRt2Yc"









VPACK_MAX_AGE = 24 * 3600



















def _vpack_keystream(key, nonce, length):









    out = bytearray()









    counter = 0









    while len(out) < length:









        out += hashlib.sha256(key + nonce + counter.to_bytes(8, "big")).digest()









        counter += 1









    return bytes(out[:length])



















def _vpack_xor(data, key, nonce):









    ks = _vpack_keystream(key, nonce, len(data))









    return bytes(a ^ b for a, b in zip(data, ks))



















def vpack_encrypt_bytes(plain):









    salt = os.urandom(16)









    nonce = os.urandom(12)









    key = hashlib.pbkdf2_hmac("sha256", VPACK_SECRET.encode(), salt, 120000, 32)









    mac_key = hashlib.pbkdf2_hmac("sha256", (VPACK_SECRET + "::mac").encode(), salt, 120000, 32)









    comp = zlib.compress(plain, 9)









    body = _vpack_xor(comp, key, nonce)









    head = VPACK_MAGIC + bytes([VPACK_VERSION]) + salt + nonce + int(time.time()).to_bytes(8, "big")









    tag = hmac.new(mac_key, head + body, hashlib.sha256).digest()









    payload = head + tag + body









    inner = base64.b85encode(payload)









    rev = inner[::-1]









    junk = os.urandom(24)









    return b"VPX6-OBF1\n" + base64.b85encode(junk + rev) + b"\n"



















def vpack_decrypt_bytes(data):









    try:









        if not data.startswith(b"VPX6-OBF1"):









            return False, None, "Magic mismatch — ye VidoPro pack nahi lagta."









        core = data.split(b"\n", 1)[1].rsplit(b"\n", 1)[0]









        raw1 = base64.b85decode(core)









        if len(raw1) <= 24:









            return False, None, "Pack too short — corrupt."









        rev = raw1[24:]









        payload = base64.b85decode(rev[::-1])









        if not payload.startswith(VPACK_MAGIC):









            return False, None, "Inner magic fail — tampered."









        ver = payload[4]









        if ver != VPACK_VERSION:









            return False, None, "Version mismatch."









        salt = payload[5:21]









        nonce = payload[21:33]









        created = int.from_bytes(payload[33:41], "big")









        tag = payload[41:73]









        body = payload[73:]









        if time.time() - created > VPACK_MAX_AGE:









            pass  # expiry hatayi gayi — coin reusable hai, kabhi bhi add karo









        key = hashlib.pbkdf2_hmac("sha256", VPACK_SECRET.encode(), salt, 120000, 32)









        mac_key = hashlib.pbkdf2_hmac("sha256", (VPACK_SECRET + "::mac").encode(), salt, 120000, 32)









        head = payload[:41]









        calc = hmac.new(mac_key, head + body, hashlib.sha256).digest()









        if not hmac.compare_digest(calc, tag):









            return False, None, "HMAC verify fail — pack tampered/edited."









        plain = zlib.decompress(_vpack_xor(body, key, nonce))









        return True, plain, "ok"









    except Exception as e:









        return False, None, f"Decrypt fail: {str(e)[:60]}"



















def shred_file_secure(path, passes=3):









    try:









        size = os.path.getsize(path)









        with open(path, "r+b") as f:









            for _ in range(passes):









                f.seek(0)









                f.write(os.urandom(max(64, size)))









                f.flush()









                os.fsync(f.fileno())









        os.remove(path)









        return True









    except Exception:









        try:









            os.remove(path)









        except Exception:









            pass









        return False



















def vpack_load_keep(path):









    try:









        with open(path, "rb") as f:









            data = f.read()









    except Exception as e:









        return False, None, f"Secure pack read fail: {str(e)[:60]}"









    ok, plain, msg = vpack_decrypt_bytes(data)









    if not ok:









        return False, None, msg









    try:









        payload = json.loads(plain.decode("utf-8", errors="ignore"))









    except Exception:









        return False, None, "Payload parse fail."









    if not isinstance(payload, dict) or payload.get("vpack") != 1 or payload.get("app") != "vidopro6":









        return False, None, "Ye VidoPro secure pack nahi hai."









    raw = payload.get("cookies_raw") or ""









    cookies = parse_cookies_input(raw)









    if not cookies:









        return False, None, "Pack me valid cookies nahi mili."









    payload["cookies"] = cookies









    return True, payload, "ok"









def vpack_load_and_shred(path):









    try:









        with open(path, "rb") as f:









            data = f.read()









    except Exception as e:









        return False, None, f"Secure pack read fail: {str(e)[:60]}"









    ok, plain, msg = vpack_decrypt_bytes(data)









    if not ok:









        return False, None, msg + " — file SAFE rakhi gayi (retry kar sakte ho)."









    try:









        payload = json.loads(plain.decode("utf-8", errors="ignore"))









    except Exception:









        return False, None, "Payload parse fail — file DESTROY kar di gayi."









    if not isinstance(payload, dict) or payload.get("vpack") != 1 or payload.get("app") != "vidopro6":









        return False, None, "Ye VidoPro secure pack nahi hai — file DESTROY kar di gayi."









    raw = payload.get("cookies_raw") or ""









    cookies = parse_cookies_input(raw)









    if not cookies:









        return False, None, "Pack me valid cookies nahi mili — file DESTROY kar di gayi."









    payload["cookies"] = cookies









    return True, payload, "ok"









