def _dlh_hw_query(cmd):









    try:









        out = subprocess.check_output(cmd, shell=True, stderr=subprocess.DEVNULL).decode(errors="ignore")









        lines = [l.strip() for l in out.splitlines() if l.strip()][1:]









        return "|".join(lines)









    except Exception:









        return ""



















def dlh_device_id():









    ps = ("powershell -NoProfile -Command \""









          "$u=(Get-CimInstance Win32_ComputerSystemProduct).UUID;"









          "$b=(Get-CimInstance Win32_BaseBoard).SerialNumber;"









          "$d=(Get-CimInstance Win32_DiskDrive | Select-Object -First 1).SerialNumber;"









          "$c=(Get-CimInstance Win32_Processor | Select-Object -First 1).ProcessorId;"









          "Write-Output ($u+'|'+$b+'|'+$d+'|'+$c)\"")









    combo = _dlh_hw_query(ps)









    if not combo or combo.count("|") < 3:









        combo = "|".join([









            _dlh_hw_query("wmic csproduct get uuid"),









            _dlh_hw_query("wmic baseboard get serialnumber"),









            _dlh_hw_query("wmic diskdrive get serialnumber"),









            _dlh_hw_query("wmic cpu get processorid"),









        ])









    fid = "SYS_" + hashlib.sha256(combo.encode()).hexdigest()[:32]









    try:









        mp = os.path.join(sub_ensure_dir(), "sys.id")









        if not os.path.isfile(mp):









            with open(mp, "w") as f:









                f.write(fid)









        else:









            old = open(mp).read().strip()









            if old.startswith("SYS_"):









                fid = old









    except Exception:









        pass









    return fid









def sub_sign(payload):









    p = dict(payload)









    ts = str(int(time.time())); nonce = base64.b32encode(os.urandom(8)).decode().strip("=")









    canon = json.dumps(p, sort_keys=True, separators=(",", ":"))









    p.update({"ts": ts, "nonce": nonce, "sig": hmac.new(SUB_SECRET.encode(), (canon + ts + nonce).encode(), hashlib.sha256).hexdigest()})









    return p



















