def vp_feature_lock_engine(app):









    global _VP_ENGINE_STARTED









    if _VP_ENGINE_STARTED:









        return









    _VP_ENGINE_STARTED = True









    import json, time, os









    time.sleep(1)









    last_sig = ""









    last_rows_str = ""









    while True:









        try:









            api_url = app._main_api_url()









            # 1. Fetch Features from Supabase /admin/features









            raw_feats = None









            try:









                res_f = sub_api_at(api_url, "/admin/features", {"op": "list"})









                if isinstance(res_f, dict) and res_f.get("features"):









                    raw_feats = res_f.get("features")









            except Exception:









                pass









            # Fallback check via /sub/verify









            if not raw_feats:









                try:









                    res_sub = sub_api("/sub/verify", {"device_id": dlh_device_id()})









                    if isinstance(res_sub, dict) and res_sub.get("features"):









                        raw_feats = res_sub.get("features")









                except Exception:









                    pass









            # Convert List to Dictionary









            feats_dict = vp_norm_features(raw_feats) if raw_feats else {}









            # 2. Fetch Settings for Hotkeys (F7, F8, F9)  # hotkey-fix-v4









            hk_dict = {}









            rows_dbg = None









            for _route in ("/admin/settings", "/admin/hotkeys"):









                for _pl in ({"op": "list"}, {"action": "list"}, {"op": "get"}, {}):









                    try:









                        res_s = sub_api_at(api_url, _route, _pl)









                    except Exception:









                        continue









                    rows = None









                    if isinstance(res_s, dict):









                        rows = res_s.get("settings") or res_s.get("hotkeys") or res_s.get("rows") or res_s.get("data")









                    if rows:









                        rows_dbg = f"{_route} {rows}"









                        rs = str(rows)









                        if rs != last_rows_str:









                            last_rows_str = rs









                            try:









                                app.log(f"🎛️ [HK RAW] route={_route} rows={rs[:220]}")









                            except Exception:









                                pass









                        hk_dict = vp_norm_hotkeys(rows)









                    if hk_dict:









                        break









                if hk_dict:









                    break









            # 2b. hotkey-fix-v4 — hotkey rows features table me bhi ho sakti hain (status ON/OFF)









            if feats_dict:









                app.sub_features = feats_dict









                for _k, _v in feats_dict.items():









                    _kk = str(_k).lower().replace("hotkey_", "")









                    if _kk in ("f7", "f8", "f9") and _kk not in hk_dict:









                        _st = str((_v or {}).get("status", "on")).lower() if isinstance(_v, dict) else str(_v).lower()









                        hk_dict[_kk] = _st in ("1", "true", "on", "yes", "enabled")









            if hk_dict:









                app.sub_hotkeys = hk_dict









            # 2c. Sync referral download link from admin settings live









            if rows:









                _r_list = rows if isinstance(rows, list) else ([rows] if isinstance(rows, dict) else [])









                for item in _r_list:









                    if isinstance(item, dict):









                        _k = str(item.get("key", "")).lower()









                        if _k in ("feat_refer_earn", "refer_earn"):









                            _st = str(item.get("value", "")).lower()









                            if _st:









                                if not isinstance(app.sub_features, dict): app.sub_features = {}









                                app.sub_features["refer_earn"] = {"status": _st}









            if rows:









                _r_list = rows if isinstance(rows, list) else ([rows] if isinstance(rows, dict) else [])









                for item in _r_list:









                    if isinstance(item, dict) and item.get("key") == "referral_download_url":









                        _ref_v = str(item.get("value", "")).strip()









                        if _ref_v:









                            app.sub_referral_download_url = _ref_v









                            _cfg = sub_load_cfg()









                            if _cfg.get("referral_download_url") != _ref_v:









                                _cfg["referral_download_url"] = _ref_v









                                sub_save_cfg(_cfg)









            # Apply in Real-Time to GUI









            # Force-apply refer_earn status









            if "refer_earn" in feats_dict or "feat_refer_earn" in feats_dict:









                rf_obj = feats_dict.get("refer_earn") or feats_dict.get("feat_refer_earn")









                if isinstance(rf_obj, dict):









                    app.sub_features["refer_earn"] = rf_obj









                else:









                    app.sub_features["refer_earn"] = {"status": str(rf_obj)}









            st_auto = str((feats_dict.get('auto_batch') or {}).get('status', 'on'))









            st_gen = str((feats_dict.get('video_generation') or {}).get('status', 'on'))









            f9_val = (getattr(app, 'sub_hotkeys', {}) or {}).get('f9', True)









            sig_parts = []









            for k in sorted(feats_dict.keys()):









                sig_parts.append(f"{k}={str((feats_dict.get(k) or {}).get('status', 'on'))}")









            hk_now = getattr(app, 'sub_hotkeys', {}) or {}









            for k in sorted(hk_now.keys()):









                sig_parts.append(f"hk_{k}={bool(hk_now.get(k))}")









            sig = "|".join(sig_parts)









            if sig != last_sig:









                last_sig = sig









                print(f"🎛️ [LIVE SYNC] auto_batch={st_auto} | F9={f9_val} | video_gen={st_gen} | hotkeys={hk_now}")









                try:









                    app.log(f"🎛️ [LIVE SYNC] hotkeys admin state: {hk_now}")









                except Exception:









                    pass









                pass  # admin_sync_debug file write disabled for security









                app.after(0, lambda fd=feats_dict: vp_apply_feature_lock(app, fd))









                app.after(0, app.sub_apply_feature_states)









        except Exception as e:









            pass









        time.sleep(3)



















