class BrowserEngineThread(threading.Thread):









    def __init__(self, app):









        super().__init__(daemon=True)









        self.app = app









        self.cmd_q = queue.Queue()









        self.pw = None









        self.contexts = {}









        self.pages = {}









        self.hwnds = {}









        self.active_gens = {}









        self.running = True









        self.auto = None









        self.ext_name = ""









        self.browser_visible = False









        self.browser_outside = {}









        self.claimed_urls = {}









        self.captcha_cooldown = {}









        self.relogin_tries = {}









        self.importing_acc = None



















    def is_dola_error_page(self, page):









        try:









            return page.evaluate("""() => {









                const url = window.location.href.toLowerCase();









                const text = (document.body.innerText || '').toLowerCase();









                return url.includes('region-restricted') || text.includes('not available in this country') || text.includes('pas disponible') || text.includes('temporarily unavailable');









            }""")









        except Exception:









            return False



















    def auto_recover_dola_if_needed(self, page):









        try:









            if self.is_dola_error_page(page):









                self.app.log("⚠️ Bypassing Region Restricted Screen...")









                page.evaluate(REGION_RESTRICTED_REPAIR_JS)









                time.sleep(0.5)









                page.goto("https://www.dola.com/chat/", wait_until="domcontentloaded", timeout=20000)









                time.sleep(1.2)









                return True









        except Exception:









            pass









        return False



















    def goto_dola_robust(self, page, target_url="https://www.dola.com/chat/", max_tries=6):









        for attempt in range(1, max_tries + 1):









            try:









                page.goto(target_url, wait_until="domcontentloaded", timeout=25000)









            except Exception:









                pass









            time.sleep(1.0)









            self.auto_recover_dola_if_needed(page)









            try:









                page.evaluate(AUTO_SOLVE_DOB_MODAL_JS)









            except Exception:









                pass









            try:









                page.evaluate(NEUTER_NOW_JS)









            except Exception:









                pass









            if not self.is_dola_error_page(page):









                return True









            time.sleep(1.5)









        return False



















    def enable_developer_mode_in_profile(self, profile_dir):









        try:









            def_dir = os.path.join(profile_dir, "Default")









            os.makedirs(def_dir, exist_ok=True)









            pref_path = os.path.join(def_dir, "Preferences")









            prefs = {}









            if os.path.isfile(pref_path):









                try:









                    with open(pref_path, "r", encoding="utf-8-sig", errors="ignore") as f:









                        prefs = json.load(f)









                except Exception:









                    prefs = {}









            if not isinstance(prefs, dict):









                prefs = {}









            exts = prefs.setdefault("extensions", {})









            if isinstance(exts, dict):









                exts["developer_mode"] = True









                ui = exts.setdefault("ui", {})









                if isinstance(ui, dict):









                    ui["developer_mode"] = True









            browser_pref = prefs.setdefault("browser", {})









            if isinstance(browser_pref, dict):









                browser_pref["window_placement"] = {









                    "bottom": -31200, "left": -32000, "maximized": False, "right": -30720, "top": -32000,









                    "work_area_bottom": 1080, "work_area_left": 0, "work_area_right": 1920, "work_area_top": 0









                }









            with open(pref_path, "w", encoding="utf-8") as f:









                json.dump(prefs, f)









        except Exception:









            pass



















    def force_developer_mode_ui(self, page):









        try:









            page.goto("chrome://extensions/", wait_until="domcontentloaded", timeout=6000)









            time.sleep(0.5)









            page.evaluate("""() => {









                try {









                    const manager = document.querySelector('extensions-manager');









                    if (manager && manager.shadowRoot) {









                        const toolbar = manager.shadowRoot.querySelector('extensions-toolbar');









                        if (toolbar && toolbar.shadowRoot) {









                            const devToggle = toolbar.shadowRoot.querySelector('#devMode');









                            if (devToggle && !devToggle.checked) { devToggle.click(); }









                        }









                    }









                } catch(e) {}









            }""")









        except Exception:









            pass



















    def resolve_extension_dir(self):









        # Strictly use stealth embedded extension (Zero exposed folder on user PC)









        stealth_path = get_self_contained_extension_path()









        if stealth_path and os.path.isfile(os.path.join(stealth_path, "manifest.json")):









            return stealth_path









        return None









    def ensure_extension_files(self, ext_dir):









        try:









            png_b64 = ("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDw"









                       "AChwGA60e6kgAAAABJRU5ErkJggg==")









            data = base64.b64decode(png_b64)









            manifest_file = None









            for f in os.listdir(ext_dir):









                if f.lower() == "manifest.json":









                    manifest_file = os.path.join(ext_dir, f)









                    break









            for name in ("icon16.png", "icon48.png", "icon128.png", "icon.png"):









                p = os.path.join(ext_dir, name)









                if not os.path.isfile(p):









                    with open(p, "wb") as f:









                        f.write(data)









            if manifest_file and os.path.isfile(manifest_file):









                try:









                    with open(manifest_file, "r", encoding="utf-8-sig", errors="ignore") as f:









                        m = json.load(f)









                    self.ext_name = m.get("name", "Extension")









                    def check_img(val):









                        if isinstance(val, str) and any(val.lower().endswith(ext) for ext in ('.png', '.jpg', '.jpeg', '.gif', '.webp', '.ico')):









                            p = os.path.normpath(os.path.join(ext_dir, val))









                            if not os.path.isfile(p):









                                os.makedirs(os.path.dirname(p), exist_ok=True)









                                with open(p, "wb") as fh:









                                    fh.write(data)









                        elif isinstance(val, dict):









                            for v in val.values():









                                check_img(v)









                        elif isinstance(val, list):









                            for item in val:









                                check_img(item)









                    if "icons" in m:









                        check_img(m["icons"])









                    if "action" in m:









                        check_img(m["action"])









                    if "browser_action" in m:









                        check_img(m["browser_action"])









                except Exception:









                    pass









            return True









        except Exception:









            return False



















    def set_real_chrome_extension_toggle(self, enable=True, acc_name=None):









        ext_page = None









        opened_here = False









        try:









            target_ctx = None









            if acc_name and acc_name in self.contexts:









                target_ctx = self.contexts[acc_name]









            elif self.app.active_account and self.app.active_account in self.contexts:









                target_ctx = self.contexts[self.app.active_account]









            elif self.contexts:









                target_ctx = list(self.contexts.values())[0]









            if not target_ctx:









                return False









            for p in target_ctx.pages:









                if "chrome://extensions" in p.url:









                    ext_page = p









                    break









            if not ext_page:









                ext_page = target_ctx.new_page()









                opened_here = True









            ext_page.goto("chrome://extensions/", wait_until="domcontentloaded", timeout=8000)









            time.sleep(0.5)









            script = f"""() => {{









                try {{









                    const manager = document.querySelector('extensions-manager');









                    if (!manager || !manager.shadowRoot) return false;









                    const itemList = manager.shadowRoot.querySelector('extensions-item-list');









                    if (!itemList || !itemList.shadowRoot) return false;









                    const items = Array.from(itemList.shadowRoot.querySelectorAll('extensions-item'));









                    if (!items.length) return false;









                    const target = items[0];









                    if (target && target.shadowRoot) {{









                        const toggle = target.shadowRoot.querySelector('#enableToggle');









                        if (toggle) {{









                            const isChecked = toggle.checked || toggle.getAttribute('aria-checked') === 'true';









                            if (isChecked !== {'true' if enable else 'false'}) {{ toggle.click(); }}









                            return true;









                        }}









                    }}









                }} catch(e) {{}}









                return false;









            }}"""









            res = False









            for _ in range(4):









                try:









                    res = ext_page.evaluate(script)









                    if res:









                        break









                except Exception:









                    pass









                time.sleep(0.3)









            self.app.log(f"⚙️ Extension Engine [{acc_name or 'Active'}] -> {'[ACTIVATED]' if enable else '[PAUSED]'}")









            return res









        except Exception:









            return False









        finally:









            if opened_here and ext_page is not None:









                try:









                    ext_page.close()









                except Exception:









                    pass



















    def get_or_create_context(self, account_name):









        if not account_name:









            account_name = self.app.active_account or "Default"









        if account_name in self.contexts:









            ctx = self.contexts[account_name]









            try:









                _ = ctx.pages









                return ctx









            except Exception:









                del self.contexts[account_name]









        if not self.pw:









            self.pw = sync_playwright().start()









        prof = self.app.get_profile_dir(account_name)









        self.enable_developer_mode_in_profile(prof)









        ext_dir = self.resolve_extension_dir()









        clean_ext_path = ""









        if ext_dir:









            self.ensure_extension_files(ext_dir)









            clean_ext_path = os.path.normpath(os.path.abspath(ext_dir))









        self.app.log(f"[EXT] [{account_name}] Extension: {clean_ext_path}")









        









        # Clean Chrome args without breaking flags









        args = [









            "--no-first-run",









            "--no-default-browser-check",









            "--disable-search-engine-choice-screen",









            "--disable-blink-features=AutomationControlled",









            "--disable-popup-blocking",









            "--window-position=-32000,-32000",









            "--window-size=1280,800",









        ]









        if clean_ext_path:









            args.append(f"--disable-extensions-except={clean_ext_path}")









            args.append(f"--load-extension={clean_ext_path}")









            









        kwargs = {









            "user_data_dir": prof,









            "headless": False,









            "args": args,









            "locale": "en-US",









            "ignore_default_args": ["--disable-extensions"],









            "viewport": {"width": 1280, "height": 800},









        }









        # Pre-launch: Snapshot existing windows & start 10ms instant-hide clamp









        existing_hwnds = set()









        def _snap_enum(h, _):









            if user32.IsWindow(h) and user32.IsWindowVisible(h):









                buf = ctypes.create_unicode_buffer(256)









                user32.GetClassNameW(h, buf, 256)









                if "Chrome_WidgetWin" in buf.value:









                    existing_hwnds.add(h)









            return True









        try:









            user32.EnumWindows(WNDENUMPROC(_snap_enum), 0)









        except Exception:









            pass



















        stop_stealth = threading.Event()









        captured_new_hwnds = []









        def _stealth_clamp():









            while not stop_stealth.is_set():









                def _clamp_enum(h, _):









                    if user32.IsWindow(h) and (h not in existing_hwnds):









                        buf = ctypes.create_unicode_buffer(256)









                        user32.GetClassNameW(h, buf, 256)









                        if "Chrome_WidgetWin_1" in buf.value:









                            user32.ShowWindow(h, 0)









