def vp_norm_hotkeys(raw):
    hk = {}
    try:
        if _vp_orig_norm_hk_v2 is not None:
            hk = dict(_vp_orig_norm_hk_v2(raw) or {})
    except Exception:
        hk = {}
    NEWK = ("f6", "f10", "f11", "f12")
    def _val(v):
        return str(v).lower().strip() in ("1", "true", "on", "yes", "enabled")
    try:
        if isinstance(raw, dict):
            for k, v in raw.items():
                kk = str(k).lower().replace("hotkey_", "").strip()
                if kk in NEWK:
                    hk[kk] = _val(v)
        elif isinstance(raw, list):
            for it in raw:
                if isinstance(it, dict):
                    kk = str(it.get("key", "") or it.get("hotkey", "") or it.get("name", "") or it.get("feature_key", "")).lower().replace("hotkey_", "").strip()
                    if kk in NEWK:
                        hk[kk] = _val(it.get("value", it.get("status", it.get("enabled", "1"))))
    except Exception:
        pass
    return hk
def _vp_hk_ok_v2(self, key):
    k = str(key).lower().replace("hotkey_", "").strip()
    if k in ("f6", "f10", "f11", "f12"):
        hk = getattr(self, "sub_hotkeys", None) or {}
        if k in hk:
            return bool(hk[k])
        f = (getattr(self, "sub_features", {}) or {}).get("hotkey_" + k) or (getattr(self, "sub_features", {}) or {}).get(k) or {}
        st = str(f.get("status", "on")).lower() if isinstance(f, dict) else str(f).lower()
        return st in ("1", "true", "on", "yes", "enabled")
    try:
        return _vp_orig_hk_ok_v2(self, key)
    except Exception:
        return True
