def _d27_find_log_widget(app):
    try:
        import tkinter as _tk27
        for w in app.winfo_children():
            try:
                if isinstance(w, _tk27.Toplevel) and "log" in (w.title() or "").lower():
                    stack = list(w.winfo_children())
                    while stack:
                        x = stack.pop()
                        if isinstance(x, _tk27.Text):
                            return x
                        stack.extend(x.winfo_children())
            except Exception:
                pass
        stack = list(app.winfo_children())
        best = None
        while stack:
            x = stack.pop()
            try:
                if isinstance(x, _tk27.Text):
                    best = x
                stack.extend(x.winfo_children())
            except Exception:
                pass
        return best
    except Exception:
        return None


def _d27_tail_start(app):
    import os as _o27
    p = _o27.path.join(_o27.path.dirname(_o27.path.abspath(__file__)), "runner_debug.log")
    st = {"pos": 0, "widget": None}
    try:
        if _o27.path.isfile(p):
            st["pos"] = _o27.path.getsize(p)
    except Exception:
        pass
    def emit(ln):
        w = st.get("widget")
        try:
            if w is None or not w.winfo_exists():
                w = _d27_find_log_widget(app)
                st["widget"] = w
        except Exception:
            w = None
        if w is not None:
            try:
                w.configure(state="normal")
                w.insert("end", "[RUNNER] " + ln + "\n")
                w.see("end")
                w.configure(state="disabled")
                return
            except Exception:
                pass
        try:
            app.log("[RUNNER] " + ln)
        except Exception:
            pass
    def tick():
        try:
            if _o27.path.isfile(p):
                sz = _o27.path.getsize(p)
                if sz < st["pos"]:
                    st["pos"] = 0
                if sz > st["pos"]:
                    with open(p, "r", encoding="utf-8", errors="replace") as f:
                        f.seek(st["pos"])
                        data = f.read()
                        st["pos"] = f.tell()
                    for ln in data.splitlines():
                        if ln.strip():
                            emit(ln)
        except Exception:
            pass
        try:
            app.after(1000, tick)
        except Exception:
            pass
    try:
        app.after(1200, tick)
    except Exception:
        pass
    try:
        app.log("🩺 [D27] runner debug tail active — backend ki raw lines ab yahan/ runner_debug.log me dikhengi.")
    except Exception:
        pass
# ==================== hotkey-fix-v27 END ====================

