def _fire_tabuid(app, p):
    try:
        if getattr(p, "_fire_tabuid", None):
            return p._fire_tabuid
        seed = _fire_user(app) + "|" + _fire_device(app) + "|T" + str(p.index)
        h = _fire_md5.md5(seed.encode("utf-8")).hexdigest()[:6].upper()
        p._fire_tabuid = "FO-" + h + "-T" + str(p.index)
        return p._fire_tabuid
    except Exception:
        return "FO-UNKNOWN-T" + str(getattr(p, "index", 1))


# ---- SA JWT (pure stdlib RS256) ----
def _fire_der_len(b, i):
    l = b[i]
    i += 1
    if l & 0x80:
        n = l & 0x7F
        l = int.from_bytes(b[i:i + n], "big")
        i += n
    return l, i


def _fire_der_children(b):
    out = []
    i = 0
    while i < len(b):
        tag = b[i]
        l, j = _fire_der_len(b, i + 1)
        out.append((tag, b[j:j + l]))
        i = j + l
    return out


def _fire_b64url(b):
    return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")


def _fire_jwt_input(sa, now):
    h = _fire_b64url(_fire_json.dumps({"alg": "RS256", "typ": "JWT"}).encode())
    c = _fire_b64url(_fire_json.dumps({"iss": str(sa.get("client_email", "")),
        "scope": "https://www.googleapis.com/auth/drive",
        "aud": "https://oauth2.googleapis.com/token", "iat": now, "exp": now + 3600}).encode())
    return h + "." + c


def _fire_sa_token(sa):
    try:
        now = int(_fire_time.time())
        if FIRE["tok"] and now < int(FIRE["tok_exp"]) - 60:
            return FIRE["tok"]
        pem = str(sa.get("private_key", "") or "")
        der = base64.b64decode("".join(pem.splitlines()[1:-1]))
        outer = _fire_der_children(der)[0][1]
        rsa_der = _fire_der_children(outer)[2][1]
        ints = [int.from_bytes(v, "big") for t, v in _fire_der_children(rsa_der) if t == 0x02]
        n, d = ints[1], ints[3]
        k = (n.bit_length() + 7) // 8
        si = _fire_jwt_input(sa, now)
        digest = hashlib.sha256(si.encode()).digest()
        t = bytes.fromhex("3031300d060960864801650304020105000420") + digest
        em = b"\x00\x01" + b"\xff" * (k - len(t) - 3) + b"\x00" + t
        sig = pow(int.from_bytes(em, "big"), d, n).to_bytes(k, "big")
        jwt = si + "." + _fire_b64url(sig)
        data = _fire_urlparse.urlencode({"grant_type": "urn:ietf:params:oauth:grant-type:jwt-bearer",
                                         "assertion": jwt}).encode()
        rq = _fire_urlreq.Request("https://oauth2.googleapis.com/token", data=data,
                                  headers={"Content-Type": "application/x-www-form-urlencoded"})
        res = _fire_json.loads(_fire_urlreq.urlopen(rq, timeout=30).read().decode())
        tok = str(res.get("access_token", "") or "")
        if tok:
            FIRE["tok"] = tok
            FIRE["tok_exp"] = now + int(res.get("expires_in", 3600) or 3600)
        return tok
    except Exception:
        return ""


def _fire_drive_req(url, tok, method="GET", data=None, ctype=None):
    h = {"Authorization": "Bearer " + tok}
    if ctype:
        h["Content-Type"] = ctype
    rq = _fire_urlreq.Request(url, data=data, headers=h, method=method)
    return _fire_urlreq.urlopen(rq, timeout=60)


def _fire_drive_list(fid, sa):
    tok = _fire_sa_token(sa)
    if not tok:
        return []
    q = _fire_urlparse.quote("'" + fid + "' in parents and trashed=false")
    url = ("https://www.googleapis.com/drive/v3/files?q=" + q +
           "&fields=files(id,name,mimeType,size)&pageSize=1000&supportsAllDrives=true&includeItemsFromAllDrives=true")
    try:
        res = _fire_json.loads(_fire_drive_req(url, tok).read().decode())
        return list(res.get("files", []) or [])
    except Exception:
        return []


def _fire_drive_upload(fid, sa, name, mime, data):
    tok = _fire_sa_token(sa)
    if not tok:
        return ""
    b = "----fireb" + str(int(_fire_time.time() * 1000))
    meta = _fire_json.dumps({"name": name, "parents": [fid]})
    body = (("--" + b + "\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n" + meta +
             "\r\n--" + b + "\r\nContent-Type: " + mime + "\r\n\r\n").encode() + data +
            ("\r\n--" + b + "--\r\n").encode())
    url = "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true"
    try:
        res = _fire_json.loads(_fire_drive_req(url, tok, "POST", body,
                                               "multipart/related; boundary=" + b).read().decode())
        return str(res.get("id", "") or "")
    except Exception:
        return ""


def _fire_drive_download(fid, sa, dest):
    tok = _fire_sa_token(sa)
    if not tok:
        return False
    try:
        resp = _fire_drive_req("https://www.googleapis.com/drive/v3/files/" + fid +
                               "?alt=media&supportsAllDrives=true", tok)
        with open(dest, "wb") as f:
            while True:
                c = resp.read(262144)
                if not c:
                    break
                f.write(c)
        return os.path.isfile(dest) and os.path.getsize(dest) > 1024
    except Exception:
        return False


def _fire_drive_delete(fid, sa):
    tok = _fire_sa_token(sa)
    if not tok:
        return False
    try:
        _fire_drive_req("https://www.googleapis.com/drive/v3/files/" + fid + "?supportsAllDrives=true",
                        tok, "DELETE")
        return True
    except Exception:
        return False


def _fire_thumb_bytes(fid, sa):
    tok = _fire_sa_token(sa)
    if not tok:
        return None
    try:
        return _fire_drive_req("https://www.googleapis.com/drive/v3/files/" + fid +
                               "?alt=media&supportsAllDrives=true", tok).read()
    except Exception:
        return None


# ---- v8: robust gather + FULL logs ----
def _fire_gather(app, p):
    prompt = ""
    for nm in ("prompt_box", "prompt_txt", "prompt_entry", "prompt", "txt_prompt",
               "prompt_input", "prompt_text", "prompt_area"):
        w = getattr(p, nm, None)
        if w is None:
            continue
        try:
            prompt = str(w.get("1.0", "end-1c") or "").strip()
        except Exception:
            try:
                prompt = str(w.get() or "").strip()
            except Exception:
                prompt = ""
        if prompt:
            break
    if not prompt:
        try:
            for vn, w in list(vars(p).items()):
                if ("prompt" in vn.lower()) and callable(getattr(w, "get", None)):
                    try:
                        t = str(w.get("1.0", "end-1c") or "").strip()
                    except Exception:
                        try:
                            t = str(w.get() or "").strip()
                        except Exception:
                            t = ""
                    if t:
                        prompt = t
                        break
        except Exception:
            pass
    if not prompt:
        found = []
        def scan(w, d):
            if d > 6 or found:
                return
            for c in list(w.winfo_children()):
                try:
                    cn = c.__class__.__name__.lower()
                    if ("text" in cn) or ("textbox" in cn):
                        try:
                            t = str(c.get("1.0", "end-1c") or "").strip()
                        except Exception:
                            t = ""
                        if t:
                            found.append(t)
                            return
                    scan(c, d + 1)
                except Exception:
                    continue
        try:
            scan(p, 0)
        except Exception:
            pass
        if found:
            prompt = found[0]
    images = []
    for nm in ("images", "ref_images", "refs", "_ref_paths", "image_paths"):
        v = getattr(p, nm, None)
        if isinstance(v, (list, tuple)):
            images = list(v)
            break
    outs = []
    for it in list(images)[:10]:
        if isinstance(it, str):
            outs.append(it)
        elif isinstance(it, dict):
            for k in ("path", "file", "p"):
                if isinstance(it.get(k), str):
                    outs.append(it[k])
                    break
    dur = 15
    ratio = "16:9"
    try:
        for vn, w in list(vars(p).items()):
            if ("dur" in vn.lower()) and callable(getattr(w, "get", None)):
                try:
                    dur = int(str(w.get()).lower().replace("s", "").strip() or 15)
                    break
                except Exception:
                    continue
    except Exception:
        pass
    try:
        for vn, w in list(vars(p).items()):
            if ("ratio" in vn.lower()) and callable(getattr(w, "get", None)):
                t = str(w.get() or "").strip()
                if ":" in t:
                    ratio = t
                    break
    except Exception:
        pass
    _fire_log(app, "🔎 [FIRE| TAB" + str(getattr(p, "index", "?")) + "] gather: prompt " +
              str(len(prompt)) + " chars, " + str(len(outs)) + " images, " + str(dur) + "s " + ratio)
    return prompt, outs, dur, ratio


def _fire_img_bytes(path):
    try:
        from PIL import Image
        im = Image.open(path).convert("RGB")
        im.thumbnail((1600, 1600))
        buf = _fire_io.BytesIO()
        im.save(buf, format="JPEG", quality=88)
        return buf.getvalue()
    except Exception:
        try:
            with open(path, "rb") as f:
                return f.read()
        except Exception:
            return b""


def _fire_click(app, p):
    _fire_log(app, "🔥 [FIRE| TAB" + str(getattr(p, "index", "?")) + "] Generate click hua.")
    try:
        _fire_card(app, p)
        _fire_card_status(p, "⏳ Fire order process ho raha hai...", "#F97316")
    except Exception:
        pass
    try:
        prompt, images, dur, ratio = _fire_gather(app, p)
    except Exception as e:
        _fire_log(app, "⚠️ [FIRE] gather error: " + str(e)[:120])
        return
    if not prompt:
        _fire_log(app, "⚠️ [FIRE| TAB" + str(getattr(p, "index", "?")) +
                  "] prompt KHALI — upar prompt box me likho, phir Generate.")
        try:
            _fire_card_status(p, "⚠️ Prompt khali hai — pehle prompt likho, phir Generate.", "#EF4444")
        except Exception:
            pass
        try:
            app.show_transient_popup("⚠️ Fire Mode: pehle prompt likho.", ms=3500)
        except Exception:
            pass
        return
    _fire_send(app, p, prompt, images, dur, ratio)


def _fire_send(app, p, prompt, images, dur, ratio):
    idx = getattr(p, "index", 1)
    tabuid = _fire_tabuid(app, p)
    _ms = int(_fire_time.time() * 1000)
    _seq = int(getattr(p, "_fire_seq", 0) or 0) + 1
    p._fire_seq = _seq
    uid = tabuid + "-" + str(_ms)[-6:] + str(_ms % 97).zfill(2) + "-" + str(_seq).zfill(2)

    def work():
        fid, sa = _fire_cfg()
        if not fid or not sa.get("client_email"):
            _fire_log(app, "⚠️ [FIRE| TAB" + str(idx) + "] config missing — fire_config.json " +
                      "(dOLA AI AUTO folder) me drive_url + sa_json hone chahiye.")
            try:
                app.after(0, lambda: _fire_ui_placed(app, p, {"uid": uid}, False,
                          "Config missing — fire_config.json software folder me daalo."))
            except Exception:
                pass
            return
        _fire_log(app, "📤 [FIRE| TAB" + str(idx) + "] Drive upload shuru — folder " +
                  str(fid)[:12] + "... SA " + str(sa.get("client_email", ""))[:30])
        img_ids = []
        for i, path in enumerate(list(images or [])[:10]):
            b = _fire_img_bytes(path)
            if b:
                iid = _fire_drive_upload(fid, sa, "IMG_" + uid + "_" + str(i) + ".jpg", "image/jpeg", b)
                if iid:
                    img_ids.append(iid)
        meta = {"uid": uid, "tabuid": tabuid, "user": _fire_user(app), "device": _fire_device(app),
                "tab": idx, "prompt": str(prompt or ""), "dur": dur, "ratio": ratio,
                "imgs": img_ids, "status": "pending", "ts": int(_fire_time.time()), "file": ""}
        oid = _fire_drive_upload(fid, sa, "ORDER_" + uid + ".json", "application/json",
                                 _fire_json.dumps(meta).encode())
        if not oid:
            _fire_log(app, "⚠️ [FIRE| TAB" + str(idx) + "] Drive upload FAIL — SA token / folder " +
                      "Editor share / Drive API check karo.")
            try:
                app.after(0, lambda: _fire_ui_placed(app, p, meta, False,
                          "Drive upload fail — folder ko SA email ke saath Editor share kiya?"))
            except Exception:
                pass
            return
        meta["order_file"] = oid
        with FIRE["lock"]:
            FIRE["orders"][uid] = meta
        _fire_log(app, "✅ [FIRE| TAB" + str(idx) + "] Order Drive me placed — UID " + uid +
                  " (" + str(len(img_ids)) + " images). Admin Vid Order me dikhega.")
        try:
            app.after(0, lambda: _fire_ui_placed(app, p, meta, True, ""))
        except Exception:
            pass
    threading.Thread(target=work, daemon=True).start()
    return True


def _fire_ui_placed(app, p, meta, ok, err):
    try:
        p._fire_cur = meta.get("uid", "")
        _fire_card(app, p)
        if ok:
            _fire_card_status(p, "🔥 Fire order placed — UID: " + meta.get("uid", "") +
                              "\nAdmin is processing. Video will appear here automatically.", "#F97316")
            try:
                p.set_result("🔥 Fire order placed. Your video will appear here when ready.", "#F97316")
            except Exception:
                pass
        else:
            _fire_card_status(p, "⚠️ " + (err or "Order fail."), "#EF4444")
    except Exception:
        pass


def _fire_card(app, p):
    try:
        c = getattr(p, "_fire_card", None)
        if c is not None and c.winfo_exists():
            return c
        import customtkinter as ctk
        c = ctk.CTkFrame(p, fg_color="#101218", corner_radius=12, border_width=1, border_color="#2A2D3A")
        c.pack(fill="x", padx=16, pady=(0, 8))
        st = ctk.CTkLabel(c, text="", font=ctk.CTkFont(size=11, weight="bold"),
                          text_color="#F97316", justify="left", wraplength=420)
        st.pack(fill="x", padx=12, pady=(10, 4))
        th = ctk.CTkLabel(c, text="")
        th.pack(padx=12, pady=(0, 10))
        p._fire_card, p._fire_card_st, p._fire_card_th = c, st, th
        return c
    except Exception:
        return None


def _fire_card_status(p, t, col):
    try:
        if getattr(p, "_fire_card_st", None) is not None and p._fire_card_st.winfo_exists():
            p._fire_card_st.configure(text=t, text_color=col)
    except Exception:
        pass


def _fire_gen_btn(p):
    b = getattr(p, "gen_btn", None)
    try:
        if b is not None and b.winfo_exists():
            return b
    except Exception:
        pass
    found = []
    def scan(w, d):
        if d > 6 or found:
            return
        for c in list(w.winfo_children()):
            try:
                t = str(c.cget("text") or "").lower()
                if ("generate" in t or "activate now" in t) and hasattr(c, "configure"):
                    try:
                        c.cget("command")
                        found.append(c)
                        return
                    except Exception:
                        pass
                scan(c, d + 1)
            except Exception:
                continue
    try:
        scan(p, 0)
    except Exception:
        pass
    return found[0] if found else None


def _fire_save_btn(p):
    try:
        b = getattr(p, "save_btn", None)
        if b is not None and b.winfo_exists():
            return b
    except Exception:
        pass
    try:
        def walk(w, d):
            if d > 6:
                return None
            for c in w.winfo_children():
                try:
                    if str(c.cget("text") or "").strip().lower() in ("save", "💾 save"):
                        return c
                except Exception:
                    pass
                r = walk(c, d + 1)
                if r is not None:
                    return r
            return None
        return walk(p, 0)
    except Exception:
        return None


def _fire_wire_save(app, p, meta):
    try:
        b = _fire_save_btn(p)
        if b is None:
            return
        if getattr(p, "_fire_save_orig", None) is None:
            try:
                p._fire_save_orig = b.cget("command")
            except Exception:
                p._fire_save_orig = None
        b.configure(state="normal", text="Save", command=lambda: _fire_save(app, p, meta["uid"]))
    except Exception:
        pass


def _fire_unwire_save(p):
    try:
        b = _fire_save_btn(p)
        if b is None:
            return
        o = getattr(p, "_fire_save_orig", None)
        b.configure(command=o if callable(o) else (lambda: None))
        p._fire_save_orig = None
    except Exception:
        pass


def _fire_ui_ready(app, p, meta):
    try:
        p._fire_cur = meta["uid"]
        _fire_card(app, p)
        _fire_card_status(p, "✅ Your video is generated — press Save to download.\nUID: " + meta["uid"], "#10B981")
        try:
            p.set_result("✅ Your video is generated — press Save to download.", "#10B981")
        except Exception:
            pass
        _fire_log(app, "🔥 [FIRE| TAB" + str(p.index) + "] Video Drive me mila (UID " + meta["uid"] + ").")
        fid, sa = _fire_cfg()
        vf = str(meta.get("file", "") or "")

        def thumb():
            b = _fire_thumb_bytes(vf, sa) if vf else None
            if not b:
                return
            try:
                from PIL import Image
                import customtkinter as ctk
                im = Image.open(_fire_io.BytesIO(b))
                im.thumbnail((420, 240))
                cim = ctk.CTkImage(light_image=im, dark_image=im, size=im.size)
                def put():
                    try:
                        if getattr(p, "_fire_card_th", None) is not None and p._fire_card_th.winfo_exists():
                            p._fire_card_th.configure(image=cim, text="")
                            p._fire_card_th.image = cim
                    except Exception:
                        pass
                app.after(0, put)
            except Exception:
                pass
        threading.Thread(target=thumb, daemon=True).start()
        _fire_wire_save(app, p, meta)
    except Exception:
        pass


def _fire_save(app, p, uid):
    with FIRE["lock"]:
        meta = dict(FIRE["orders"].get(uid) or {})
    if not meta:
        return
    b = _fire_save_btn(p)
    try:
        if b is not None:
            b.configure(state="disabled", text="Saving...")
    except Exception:
        pass
    _fire_card_status(p, "⬇️ Downloading your video from Drive...", "#38BDF8")

    def work():
        fid, sa = _fire_cfg()
        vdir = os.path.join(BASE, "VidoPro Videos")
        try:
            os.makedirs(vdir, exist_ok=True)
        except Exception:
            pass
        dest = os.path.join(vdir, uid + ".mp4")
        ok = _fire_drive_download(str(meta.get("file", "")), sa, dest)
        if not ok:
            try:
                app.after(0, lambda: _fire_card_status(p, "⚠️ Download fail — dobara Save dabao.", "#EF4444"))
                app.after(0, lambda: _fire_wire_save(app, p, meta))
            except Exception:
                pass
            return
        deleted = _fire_drive_delete(str(meta.get("file", "")), sa)
        for iid in list(meta.get("imgs", []) or []):
            _fire_drive_delete(str(iid), sa)
        if meta.get("order_file"):
            _fire_drive_delete(str(meta["order_file"]), sa)
        with FIRE["lock"]:
            FIRE["orders"].pop(uid, None)

        def done():
            try:
                _fire_card_status(p, "✅ Video saved: " + os.path.basename(dest) +
                                  ("\n🧹 Drive video + order auto-delete." if deleted else
                                   "\n⚠️ Drive auto-delete skip (SA permission)."),
                                  "#10B981" if deleted else "#F59E0B")
                try:
                    p.set_result("✅ Video saved: " + dest, "#10B981")
                except Exception:
                    pass
                _fire_log(app, "💾 [FIRE| TAB" + str(p.index) + "] Video saved: " + dest)
                _fire_unwire_save(p)
                try:
                    if b is not None:
                        b.configure(state="normal", text="Save")
                except Exception:
                    pass
            except Exception:
                pass
        try:
            app.after(0, done)
        except Exception:
            pass
    threading.Thread(target=work, daemon=True).start()


def _fire_poll(app):
    now = _fire_time.time()
    if now - float(FIRE["poll_t"]) < 20:
        return
    FIRE["poll_t"] = now
    with FIRE["lock"]:
        pend = [dict(m) for m in FIRE["orders"].values() if str(m.get("status", "")) == "pending"]
    if not pend:
        return
    fid, sa = _fire_cfg()
    if not fid or not sa.get("client_email"):
        return

    def work():
        files = _fire_drive_list(fid, sa)
        for meta in pend:
            uid = str(meta.get("uid", ""))
            hit = ""
            for f in files:
                nm = str(f.get("name", ""))
                if nm.lower().startswith(uid.lower()) and not nm.startswith(("ORDER_", "IMG_")):
                    hit = str(f.get("id", ""))
                    break
            if not hit:
                continue
            meta["status"] = "ready"
            meta["file"] = hit
            with FIRE["lock"]:
                FIRE["orders"][uid] = meta
            try:
                p = app.get_panel(int(meta.get("tab", 0)))
                if p is not None:
                    app.after(0, lambda q=p, m=dict(meta): _fire_ui_ready(app, q, m))
            except Exception:
                pass
    threading.Thread(target=work, daemon=True).start()


def _fire_load(app):
    if FIRE["loaded"]:
        return
    FIRE["loaded"] = True
    fid, sa = _fire_cfg()
    if not fid or not sa.get("client_email"):
        return
    dev = _fire_device(app)

    def work():
        for f in _fire_drive_list(fid, sa):
            nm = str(f.get("name", ""))
            if not nm.startswith("ORDER_"):
                continue
            try:
                meta = _fire_json.loads(_fire_drive_req(
                    "https://www.googleapis.com/drive/v3/files/" + str(f.get("id")) +
                    "?alt=media&supportsAllDrives=true", _fire_sa_token(sa)).read().decode())
            except Exception:
                continue
            if str(meta.get("device", "")) != dev:
                continue
            meta["order_file"] = str(f.get("id"))
            with FIRE["lock"]:
                FIRE["orders"][str(meta.get("uid", ""))] = meta
    threading.Thread(target=work, daemon=True).start()


# ---- GUI ----
def _fire_style(p, on):
    try:
        b = getattr(p, "_fire_btn", None)
        if b is None:
            return
        b.configure(fg_color=FIRE_ACCENT if on else "transparent",
                    text_color="#FFFFFF" if on else FIRE_IDLE_TX)
    except Exception:
        pass


def _fire_select(app, p):
    try:
        try:
            p.switch_mode("r2v")
        except Exception:
            pass
        p._vp_fire = True
        p._fire_wired_btn = None
        try:
            p._vp_pro_new = False
            p._vp_legit2 = False
            p._vp_pro_new2 = False
        except Exception:
            pass
        _fire_style(p, True)
        try:
            if getattr(p, "r2v_btn", None) is not None:
                p.r2v_btn.configure(fg_color="transparent", text_color=FIRE_IDLE_TX)
        except Exception:
            pass
        _fire_clean_panel(app, p)
        _fire_log(app, "🔥 [TAB" + str(p.index) + "] Fire Mode select — Generate = order (koi activation NAHI).")
    except Exception:
        pass


def _fire_ensure_btn(app, p):
    try:
        b = getattr(p, "_fire_btn", None)
        if b is not None:
            try:
                if not b.winfo_exists():
                    b = None
                    p._fire_btn = None
            except Exception:
                b = None
        if b is None:
            mr = getattr(p, "mode_row", None)
            if mr is None:
                return
            import customtkinter as ctk
            b = ctk.CTkButton(mr, text="Fire Mode", width=95, height=28,
                              font=ctk.CTkFont(size=11, weight="bold"),
                              fg_color="transparent", hover_color="#1F2430",
                              text_color=FIRE_IDLE_TX, corner_radius=6,
                              command=lambda q=p: _fire_select(app, q), cursor="hand2")
            p._fire_btn = b
            try:
                a = getattr(p, "r2v_btn", None)
                if a is not None and a.winfo_exists():
                    b.pack(side="left", padx=2, pady=4, after=a)
                else:
                    b.pack(side="left", padx=2, pady=4)
            except Exception:
                try:
                    b.pack(side="left", padx=2, pady=4)
                except Exception:
                    pass
        _fire_style(p, bool(getattr(p, "_vp_fire", False)))
    except Exception:
        pass


def _fire_wrap_switch(app, p):
    try:
        if getattr(p, "_fire_switch_wrapped", False):
            return
        orig = getattr(p, "switch_mode", None)
        if not callable(orig):
            return
        p._fire_switch_wrapped = True
        def switch_mode(mode, *a, **k):
            try:
                # fire-fix-v9: fire r2v UI use karta hai -> r2v internal calls par clear NAHI.
                if str(mode) in ("t2v", "i2v", "legit"):
                    p._vp_fire = False
                    p._fire_wired_btn = None
                    _fire_style(p, False)
            except Exception:
                pass
            return orig(mode, *a, **k)
        p.switch_mode = switch_mode
    except Exception:
        pass


def _fire_clean_panel(app, p):
    if not bool(getattr(p, "_vp_fire", False)):
        return
    try:
        ov = getattr(p, "_vp_m2_ov", None)
        if ov is not None and ov.winfo_exists() and ov.winfo_ismapped():
            try:
                ov.place_forget()
                ov.pack_forget()
            except Exception:
                pass
    except Exception:
        pass
    try:
        def scan2(w, d):
            if d > 4:
                return
            for c in list(w.winfo_children()):
                try:
                    isb = False
                    try:
                        c.cget("command")
                        isb = True
                    except Exception:
                        isb = False
                    if not isb:
                        tl = str(c.cget("text") or "").lower()
                        if ("deactive" in tl) or ("activating" in tl):
                            try:
                                c.configure(text="● Fire Mode")
                            except Exception:
                                pass
                            for kw in ({"text_color": "#F97316", "fg_color": "#FFEDD5"},
                                       {"fg": "#F97316", "bg": "#FFEDD5"}):
                                try:
                                    c.configure(**kw)
                                except Exception:
                                    pass
                    scan2(c, d + 1)
                except Exception:
                    continue
        scan2(p, 0)
    except Exception:
        pass
    # v8: command SIRF EK BAAR wire (har tick re-set karne se CTk click marta tha)
    try:
        btn = _fire_gen_btn(p)
        if btn is not None and btn.winfo_exists():
            st = getattr(p, "_v24_act", None)
            if isinstance(st, dict):
                st["swapped"] = False
                st["busy"] = False
            _cur = None
            try:
                _cur = btn.cget("command")
            except Exception:
                _cur = None
            if not getattr(_cur, "_fire_mine", False):
                def _fc(q=p):
                    _fire_click(app, q)
                _fc._fire_mine = True
                btn.configure(command=_fc)
                p._fire_wired_btn = btn
                _fire_log(app, "🔗 [FIRE| TAB" + str(getattr(p, "index", "?")) +
                          "] Generate command (re)assert — click = order, activation NAHI.")
            try:
                if "generate" not in str(btn.cget("text") or "").lower():
                    btn.configure(text="⚡ Generate")
                if str(btn.cget("state")) == "disabled":
                    btn.configure(state="normal")
            except Exception:
                pass
    except Exception:
        pass


def _fire_hook_va_tick(app):
    try:
        import vp_pro_activate as va
        o = getattr(va, "_tick", None)
        if o is None or getattr(o, "_fire8", False):
            return
        def _t8(*a, **k):
            r = o(*a, **k)
            try:
                for q in list(getattr(app, "panels", []) or []):
                    try:
                        _fire_clean_panel(app, q)
                    except Exception:
                        pass
            except Exception:
                pass
            return r
        _t8._fire8 = True
        va._tick = _t8
    except Exception:
        pass


def _fire_wrap_pro_btn(app, p):
    # fire-fix-v9: user Pro Mode button dabaye to fire clear (programmatic r2v se alag).
    try:
        if getattr(p, "_fire_pro_wrapped", False):
            return
        b = getattr(p, "r2v_btn", None)
        if b is None or not b.winfo_exists():
            return
        orig = None
        try:
            orig = b.cget("command")
        except Exception:
            orig = None
        if not callable(orig):
            return
        p._fire_pro_wrapped = True
        def _pro(*a, **k):
            try:
                p._vp_fire = False
                p._fire_wired_btn = None
                _fire_style(p, False)
            except Exception:
                pass
            return orig(*a, **k)
        b.configure(command=_pro)
    except Exception:
        pass


def _fire_tick(app):
    try:
        _fire_load(app)
        for p in list(getattr(app, "panels", []) or []):
            try:
                _fire_wrap_switch(app, p)
                _fire_wrap_pro_btn(app, p)
                if (getattr(p, "_vp_pro_new", False) or getattr(p, "_vp_legit2", False)
                        or getattr(p, "_vp_pro_new2", False)):
                    p._vp_fire = False
                    _fire_style(p, False)
                _fire_ensure_btn(app, p)
                _fire_clean_panel(app, p)
            except Exception:
                pass
        _fire_poll(app)
    except Exception:
        pass
    try:
        app.after(900, lambda: _fire_tick(app))
    except Exception:
        pass


def _fire_boot_hook(app):
    return  # vp-fire-module-v10: purana fire block DISABLE (ab vp_fire_mode.py dedicated)
    try:
        if FIRE["inst"]:
            return
        FIRE["inst"] = True
        try:
            orig_send = app.send_browser_cmd
            def send_browser_cmd(cmd):
                try:
                    if isinstance(cmd, (tuple, list)) and cmd and cmd[0] == "generate":
                        pnl = app.get_panel(cmd[1])
                        if pnl is not None and getattr(pnl, "_vp_fire", False):
                            pr = cmd[3] if len(cmd) > 3 else ""
                            im = list(cmd[4] or []) if len(cmd) > 4 else []
                            du = cmd[5] if len(cmd) > 5 else 15
                            ra = cmd[6] if len(cmd) > 6 else "16:9"
                            _fire_send(app, pnl, pr, im, du, ra)
                            return None
                except Exception:
                    pass
                return orig_send(cmd)
            app.send_browser_cmd = send_browser_cmd
        except Exception:
            pass
        try:
            _fire_hook_va_tick(app)
        except Exception:
            pass
        if not FIRE["tick"]:
            FIRE["tick"] = True
            try:
                app.after(900, lambda: _fire_tick(app))
            except Exception:
                pass
        _fire_log(app, "🔥 [" + FIRE_VER + "] Fire Mode ready — click par full logs + order Drive me.")
    except Exception:
        pass
